  m2 = m
  a1 = -1 * vx * x % m1
  a2 = -1 * vy * y % m2
  if a1 % g != a2 % g:
    print("-1")
    return 0
  if GCD(m1//g,m2) == 1:
    m1 = m1 // g
  else:
    m2 = m2 // g
  m1_bar = INV(m2,m1)
  m2_bar = INV(m1,m2)
  k = (a1 * m1_bar*m2 + a2 * m2_bar*m1) % (m1*m2)
  rowtouch = ((k+m-1)//m) % 2
  coltouch = ((k+n-1)//n) % 2
  ans = [0,0]
