def gcd(a, b):
    if (b == 0):
        return a
    return gcd(b, a % b)

def exgcd(a, b):
    if (b == 0):
        return (1, 0, a)
    (p, q, r) = exgcd(b, a % b)
    t = p
    p = q
    q = t - (a // b) * q
    return (p, q, r)
