class segment_tree_mergesort:
    ###building the tree in our init method
    def __init__(self,arr):
        self.arr=arr
        self.l=len(arr)
        import math
        h=math.floor(math.log2(self.l)+1)
        ###of tree size 2**(math.ceil(log2(n))+1)
        self.st=[[] for x in range(2**(h+1)+1)]
        ###not use * as same list object at all loctions
        self.si=1 ##segment index
        self.ss=0 ##segment start ##arr start
        self.se=self.l-1  ###segment end ##arr end
        self.__buildmintree(self.si,self.ss,self.se)

    def __buildmintree(self,si,ss,se):
        if ss==se:
            self.st[si]=[self.arr[ss]]
            return True

        mid=(ss+se)//2
        self.__buildmintree(2*si,ss,mid)
        self.__buildmintree(2*si+1,mid+1,se)
        i=0;j=0
        while i<len(self.st[2*si]) and j<len(self.st[2*si+1]):
            if self.st[2*si][i]<=self.st[2*si+1][j]:
                self.st[si].append(self.st[2*si][i])
                i+=1
            else:
                self.st[si].append(self.st[2*si+1][j])
                j+=1
        while i<len(self.st[2*si]):
            self.st[si].append(self.st[2*si][i])
            i+=1
        while j<len(self.st[2*si+1]):
            self.st[si].append(self.st[2*si+1][j])
            j+=1
    ## no  of elemests les than k
    def query(self,si,ss,se,qs,qe,type):
        ##segment outside query
        if se<qs or qe<ss:
            return 0

        ###segment inside query
        if qs<=ss and  se<=qe:
            if type==1:
                return less(self.st[si],0,len(self.st[si])-1)
            else:
                return greater(self.st[si],0,len(self.st[si])-1)

        mid=(ss+se)//2
        l=self.query(2*si,ss,mid,qs,qe,type)
        r=self.query(2*si+1,mid+1,se,qs,qe,type)
        return l+r

