import collections

def solve(n, d, a):
    sol, q = 0, collections.deque([(i, 0) for i, x in enumerate(a) if x == 0])
    while q:
        i, s = q.popleft()
        ii = (i + d) % n
        if a[ii] == 1:
            a[ii] = 0
            q.append((ii, s+1))
        sol = max(sol, s)
    return sol if sum(a) == 0 else -1

