    for i in arr:
        count[i] += 1
    ans = [-1 for _ in range(n+1)]
    ans[0] = count[0]
    if not ans[0]:
        return ans

    steps = 0
    last = []
    if ans[0] > 1:
        last.append(0)

    for i in range(1, n+1):
        if arr[i-1] >= i:
            continue
        ans[i] = count[i] + steps

        if count[i] > 1:
            last.append(i)

        if not count[i]:
            if not last:
                return ans
            steps += (i - last[-1])
            count[last[-1]] -= 1
            if count[last[-1]] == 1:
                last.pop()
    return ans

